import{_ as t,o,c as d,a2 as a}from"./chunks/framework.DrWxItG4.js";const g=JSON.parse('{"title":"Login on the official servers","description":"","frontmatter":{},"headers":[],"relativePath":"guide/official-login.md","filePath":"guide/official-login.md"}'),n={name:"guide/official-login.md"};function s(r,e,c,i,l,h){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="login-on-the-official-servers" tabindex="-1">Login on the official servers <a class="header-anchor" href="#login-on-the-official-servers" aria-label="Permalink to &quot;Login on the official servers&quot;">​</a></h1><p>This page follows what the 5.60 Android client does when it logs in to the official servers, step by step. Everything comes from the client&#39;s own code (<code>libgrowtopia.so</code> and its Java side), not from watching the official servers. For what gurotopia and GrowServer accept, see <a href="/gtps-guide/guide/login">Login</a>.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>client                      growtopia1/2.com            login site (loginurl)          ENet servers</span></span>\n<span class="line"><span>  |                               |                             |                           |</span></span>\n<span class="line"><span>  |-- POST server_data.php ------&gt;|                             |                           |</span></span>\n<span class="line"><span>  |&lt;-- server|port|loginurl|... --|                             |                           |</span></span>\n<span class="line"><span>  |                                                             |                           |</span></span>\n<span class="line"><span>  |-- saved token?  yes: POST &lt;checktoken&gt;  (refreshToken) ----&gt;|                           |</span></span>\n<span class="line"><span>  |                 no:  WebView POST /player/login/dashboard --&gt;|  (player signs in)        |</span></span>\n<span class="line"><span>  |&lt;-- JSON {status:&quot;success&quot;, token, accountType, accountAge} -|                           |</span></span>\n<span class="line"><span>  |                                                                                         |</span></span>\n<span class="line"><span>  |-- ENet connect server:port, send  protocol|ltoken|platformID|...  -----&gt; login server   |</span></span>\n<span class="line"><span>  |&lt;-- OnSendToServer(port, token, user, &quot;ip|doorID|uuid&quot;, lmode, growid) ------------------|</span></span>\n<span class="line"><span>  |-- DISCONNECT, connect ip:port, send  tankIDName|...|user|token|UUIDToken|doorID|aat --&gt; game server</span></span>\n<span class="line"><span>  |&lt;-- OnSuperMainStartAcceptLogon…  -&gt;  action|enter_game  -&gt;  world menu                  |</span></span></code></pre></div><p>The connection screen keeps a state number through all of this (<code>+0x40c</code>): 0 getting the server address, 1 web login, 2 captcha, 3 connecting to the login server, 4 handed over to a game server. Each change is also reported to the client&#39;s analytics (<code>0x1b6fbc0</code>).</p><h2 id="_1-server-data-php" tabindex="-1">1. server_data.php <a class="header-anchor" href="#_1-server-data-php" aria-label="Permalink to &quot;1. server_data.php&quot;">​</a></h2><p>The client asks a web server where to connect. While waiting it shows &quot;Getting <code> `wserver address</code> ``...&quot;.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>URL</td><td><code>https://www.growtopia1.com/growtopia/server_data.php</code>; the retry uses <code>www.growtopia2.com</code> and adds &quot;(using alternate)&quot; to the text</td></tr><tr><td>Method</td><td>POST, form-encoded, through the client&#39;s CURL wrapper. Redirects to a non-HTTPS URL are refused</td></tr><tr><td>Body</td><td><code>version=5.6&amp;protocol=227&amp;platform=&lt;n&gt;</code></td></tr></tbody></table><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><code>version</code></td><td>the game version as a float, <code>5.6</code> (<code>0x107fe6c</code>)</td></tr><tr><td><code>protocol</code></td><td>the protocol number, <code>227</code> in 5.60. The ENet login messages send the same number</td></tr><tr><td><code>platform</code></td><td>the platform number (<code>0x14213cc</code>). The ENet login sends the same number as <code>platformID</code></td></tr></tbody></table><p>The reply is <code>key|value</code> lines. The client reads these keys, so a line it doesn&#39;t know about is ignored (<code>RTENDMARKERBS1001</code> and <code>type2</code>, for example):</p><table tabindex="0"><thead><tr><th>Key</th><th>Used as</th></tr></thead><tbody><tr><td><code>error</code></td><td><code>error|&lt;code&gt;|&lt;message&gt;</code>: the message is shown and logged. Code <code>1000</code> means the client is too old: it reads <code>url</code> and shows an <strong>Update Growtopia</strong> button (or <strong>Download Latest Version</strong> on some platforms), and the login stops</td></tr><tr><td><code>url</code></td><td>the download link for <code>error|1000</code></td></tr><tr><td><code>server</code></td><td>the login server&#39;s address</td></tr><tr><td><code>port</code></td><td>its ENet port</td></tr><tr><td><code>type</code></td><td>stored at app+0xbe0 when connecting; what it changes wasn&#39;t traced</td></tr><tr><td><code>maint</code></td><td>if it isn&#39;t empty, the text is shown and the login stops there (maintenance)</td></tr><tr><td><code>loginurl</code></td><td>the host of the login site, used in step 2</td></tr><tr><td><code>endpoint</code></td><td>the login page&#39;s path, default <code>/player/login/dashboard</code></td></tr><tr><td><code>checktoken</code></td><td>the path for checking a saved token, default <code>player/growid/checktoken</code></td></tr><tr><td><code>beta_server</code>, <code>beta_port</code>, <code>beta_maint</code>, <code>beta_type</code>, <code>beta_loginurl</code></td><td>used in place of the normal values when the client is in beta mode (see <a href="/gtps-guide/functions/OnSetBetaMode">OnSetBetaMode</a>); <code>beta2_*</code> and <code>beta3_*</code> work the same way for two more beta flags</td></tr><tr><td><code>meta</code></td><td>stored in the app and sent back as <code>meta|</code> in the login message (step 4)</td></tr></tbody></table><p>If the HTTP status isn&#39;t 200, the client tries again up to 4 times. Each retry switches between growtopia1 and growtopia2 and logs &quot;Get web front, retry login&quot;. After that it shows &quot;<code> `4During login request an error occurred: fail to login. Please try to login again.</code> <code>&quot;. Network errors show &quot;</code> `4Unable to connect to the network.<code></code>&quot;.</p><p>A developer setting (a server override, app+0xa28) skips the request and loads a built-in reply that points to <code>localhost:16999</code> instead.</p><p><small>Request: <code>0x1b6ea04</code>; reply parser: <code>0x1b700fc</code>; retry on error: <code>0x1b7f95c</code>.</small></p><h2 id="_2-the-login-site" tabindex="-1">2. The login site <a class="header-anchor" href="#_2-the-login-site" aria-label="Permalink to &quot;2. The login site&quot;">​</a></h2><p>Next the client needs a <strong>token</strong> from the login site, <code>https://&lt;loginurl&gt;</code>. All of its requests also send a fixed <code>valKey</code> query parameter that is built into the client. Its value isn&#39;t given here.</p><p><strong>With a saved token</strong>: when the client has a token from an earlier login and a saved GrowID name (the <code>tankid_name</code> setting), it checks the token instead of showing the login page. It logs &quot;Validate token.&quot; and POSTs <code>refreshToken=&lt;saved token&gt;&amp;clientData=&lt;login message&gt;</code> to <code>https://&lt;loginurl&gt;/&lt;checktoken&gt;?valKey=…</code>.</p><p><strong>Otherwise</strong>: it logs &quot;Request login token.&quot; and opens a WebView that POSTs <code>clientData</code> to <code>https://&lt;loginurl&gt;/player/login/dashboard?valKey=…</code>. The player signs in on that page, with a GrowID, Google, Apple or Ubisoft Connect, and a <strong>Cancel</strong> button under the page stops the login.</p><p><code>clientData</code> is the same text as the ENet login message from step 4, built by the same function (<code>0x180145c</code>) and URL-encoded. That way the site knows the device and game version before the game server does.</p><h3 id="how-the-page-hands-the-token-back" tabindex="-1">How the page hands the token back <a class="header-anchor" href="#how-the-page-hands-the-token-back" aria-label="Permalink to &quot;How the page hands the token back&quot;">​</a></h3><p>The WebView exposes a JavaScript object named <code>NativeApp</code> to the page:</p><table tabindex="0"><thead><tr><th>Method</th><th>What the client does</th></tr></thead><tbody><tr><td><code>NativeApp.nativeSignIn(x)</code></td><td>starts the platform&#39;s own sign-in (Google on Android). The result goes to <code>https://&lt;loginurl&gt;/google/native/callback?code=&lt;code&gt;&amp;token=&lt;token&gt;</code>, opened in the same WebView (&quot;Send native token.&quot;)</td></tr><tr><td><code>NativeApp.onloginselection(x)</code>, <code>NativeApp.onnameselection(x)</code></td><td>passed to the native code as script calls (<code>nativeOnScriptCall</code>)</td></tr><tr><td><code>NativeApp.pageContent(text)</code></td><td>hands the page&#39;s text to the native code</td></tr><tr><td><code>NativeApp.openInBrowser(url)</code></td><td>opens the link in the system browser. Links with <code>target=&quot;_blank&quot;</code> do the same</td></tr></tbody></table><p>The answer is JSON. For the dashboard it is read from the page text (<code>pageContent</code>); for <code>checktoken</code> it is the response body. The client reads it as follows (<code>0x1b99a54</code>):</p><table tabindex="0"><thead><tr><th><code>status</code></th><th>What happens</th></tr></thead><tbody><tr><td><code>success</code></td><td>reads <code>token</code>, <code>accountType</code> and <code>accountAge</code>, closes the WebView and continues to step 3</td></tr><tr><td><code>failed</code></td><td>shows <code>message</code> in red, if there is one</td></tr><tr><td><code>close</code></td><td>shows &quot;<code>`4You don&#39;t have permission to continue playing`</code>&quot;</td></tr><tr><td><code>unlinked</code></td><td>reads <code>accountType</code> and starts that account type&#39;s linking flow (not traced further)</td></tr><tr><td>anything else</td><td>&quot;<code> `4During login request an error occurred: fail to get validation status. Please try to login again.</code> ``&quot;</td></tr></tbody></table><p><code>status</code> and <code>token</code> must both be strings, or the client shows &quot;…fail to get validation response…&quot;. The <code>accountType</code> strings the client knows are <code>growtopia</code>, <code>apple</code>, <code>google</code> and <code>ubiconnect</code> (<code>0x1b9e04c</code>). <code>accountAge</code> is one of the client&#39;s age types: None, Kid, Teenage, Adult, AdultNotVerified.</p><p>What the client does with a good answer (<code>0x1b72ab0</code>):</p><ol><li>It keeps the token, which becomes the <code>ltoken</code> in step 3, and the account type.</li><li>It applies the age type. Depending on it, the client turns on friends-only chat and switches off some features (probably the limits for younger players). For one age type it first shows an adult-verification notice, once.</li><li>It closes the WebView and connects (step 3).</li></ol><p>The token is saved to the <code>Token</code> setting, with the account type in <code>LoginAccountType</code>, only after the login server has accepted it and sent <code>OnSendToServer</code>. That saved token is what the next launch checks.</p><p>If a deep link opens the app during the web login (for example after signing in through the system browser), the client opens <code>https://&lt;loginurl&gt;/&lt;path from the link&gt;</code> in the WebView (<a href="#5-game-messages-during-login">OnGetDeeplinkData</a>).</p><h2 id="_3-enet-the-login-server" tabindex="-1">3. ENet: the login server <a class="header-anchor" href="#_3-enet-the-login-server" aria-label="Permalink to &quot;3. ENet: the login server&quot;">​</a></h2><p>The client shows &quot;Located <code> `wserver</code> <code>, connecting...&quot; (&quot;</code> <code>5beta server`` ``&quot; and so on in beta mode), sets the logon mode to 0 and connects to </code>server:port<code> with [ENet](/guide/transport). After the server&#39;s [HELLO](/messages/1-server-hello) it sends one [GENERIC_TEXT](/messages/2-generic-text) message (</code>0x1805e08`):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>protocol|227</span></span>\n<span class="line"><span>ltoken|&lt;token from step 2&gt;</span></span>\n<span class="line"><span>platformID|&lt;platform&gt;</span></span>\n<span class="line"><span>rcdl|&lt;redeem code&gt;          only when the app was opened with a redeem-code link</span></span>\n<span class="line"><span>adc|&lt;0 or 1&gt;                the AppleConsent setting</span></span></code></pre></div><p>The login server answers in one of these ways:</p><ul><li><a href="/gtps-guide/functions/OnSendToServer">OnSendToServer</a><code>(port, token, user id, &quot;ip|doorID|uuid&quot;, logon mode, growid)</code>: the token was accepted. The client disconnects (sending a <a href="/gtps-guide/packets/1a-disconnect">DISCONNECT (0x1a)</a>) and connects to <code>ip:port</code> (step 4).</li><li><code>action|logon_fail</code> (<a href="/gtps-guide/messages/3-game-message">GAME_MESSAGE</a>): with logon mode 0 the client disconnects. Otherwise it disconnects and reconnects after 2 seconds.</li><li>One of the text commands in <a href="#5-game-messages-during-login">Game messages during login</a>.</li></ul><h2 id="_4-enet-the-game-server" tabindex="-1">4. ENet: the game server <a class="header-anchor" href="#_4-enet-the-game-server" aria-label="Permalink to &quot;4. ENet: the game server&quot;">​</a></h2><p>The client connects to the address from <code>OnSendToServer</code> and, after HELLO, sends the full login message (<code>0x18009d0</code>). It is the same text that went to the login site as <code>clientData</code>, with the redirect values at the end. Fields are in this order, each as <code>key|value\\n</code>:</p><table tabindex="0"><thead><tr><th>Field</th><th>What it is</th></tr></thead><tbody><tr><td><code>tr</code></td><td>first, only when present (not traced)</td></tr><tr><td><code>tankIDName</code>, <code>tankIDPass</code></td><td>the saved GrowID name and password; sent only when the &quot;remember&quot; setting (<code>tankid_checkbox</code>) is on</td></tr><tr><td><code>requestedName</code></td><td>the saved <code>name</code> setting (the name a new player asked for)</td></tr><tr><td><code>f</code></td><td>the swear-filter setting</td></tr><tr><td><code>protocol</code></td><td>227</td></tr><tr><td><code>game_version</code></td><td>5.6</td></tr><tr><td><code>fz</code></td><td>an integrity value</td></tr><tr><td><code>cbits</code></td><td>client setting bits</td></tr><tr><td><code>hash2</code></td><td>a device hash</td></tr><tr><td><code>vid</code>, <code>aid</code>, <code>gid</code></td><td>device and advertising ids (probably vendor, Android and Google ad ids)</td></tr><tr><td><code>meta</code></td><td>the <code>meta</code> from server_data.php</td></tr><tr><td><code>rid</code></td><td>an id the client creates once and saves (<code>rid</code> setting)</td></tr><tr><td><code>platformID</code></td><td>the platform number</td></tr><tr><td><code>deviceVersion</code></td><td>the device&#39;s OS version (probably)</td></tr><tr><td><code>country</code></td><td>the country code</td></tr><tr><td><code>hash</code></td><td>a device hash</td></tr><tr><td><code>mac</code></td><td>the device&#39;s MAC address, or a placeholder</td></tr><tr><td><code>user</code>, <code>token</code>, <code>doorID</code></td><td>from <code>OnSendToServer</code></td></tr><tr><td><code>wk</code></td><td>a device key (probably)</td></tr><tr><td><code>fhash</code></td><td>an integrity hash</td></tr><tr><td><code>GDPR</code></td><td>the consent value (app+0xc2c)</td></tr><tr><td><code>player_age</code></td><td>the age value (app+0xc30)</td></tr><tr><td><code>assign_button_inverted</code></td><td>a controls setting</td></tr><tr><td><code>category</code></td><td>the saved <code>last_Category</code> setting</td></tr><tr><td><code>totalPlaytime</code></td><td>the saved total play time</td></tr><tr><td><code>klv</code></td><td>a checksum the server uses to detect modified clients</td></tr><tr><td><code>lmode</code></td><td>the logon mode from <code>OnSendToServer</code></td></tr><tr><td><code>reconnect</code></td><td><code>1</code>, when this is a reconnect</td></tr><tr><td><code>FCMToken</code></td><td>the Firebase push token</td></tr></tbody></table><p>After a redirect, the builder then appends (<code>0x18009d0</code>):</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><code>reconnect</code></td><td><code>1</code>, if the connection is flagged as a reconnect</td></tr><tr><td><code>lmode</code></td><td>the logon mode from <code>OnSendToServer</code> argument 5</td></tr><tr><td><code>user</code></td><td>the user id from argument 3</td></tr><tr><td><code>token</code></td><td>the token from argument 2, if it isn&#39;t 0</td></tr><tr><td><code>UUIDToken</code></td><td>the third part of argument 4</td></tr><tr><td><code>doorID</code></td><td>the second part of argument 4</td></tr><tr><td><code>aat</code></td><td>a value from the login account (probably the account age type from step 2)</td></tr></tbody></table><p>The integrity values (<code>fz</code>, <code>hash</code>, <code>hash2</code>, <code>fhash</code>, <code>klv</code>, <code>wk</code>, <code>rid</code> and the device ids) are only described here, not how they are made. They exist so the official servers can recognise their own client.</p><p>The game server then sends <a href="/gtps-guide/functions/OnSuperMainStartAcceptLogonHrdxs47254722215a">OnSuperMainStartAcceptLogonHrdxs47254722215a</a>. The client checks its items.dat and player_tribute.dat hashes, downloads newer files from the CDN it was given, and answers with <a href="/gtps-guide/actions/enter_game">action|enter_game</a>. With logon mode 2 or more it skips the file checks and sends <code>enter_game</code> straight away. From there it is the same as on a private server; see <a href="/gtps-guide/guide/login#what-the-server-sends-after-enter-game">What the server sends after enter_game</a>.</p><h2 id="_5-game-messages-during-login" tabindex="-1">5. Game messages during login <a class="header-anchor" href="#_5-game-messages-during-login" aria-label="Permalink to &quot;5. Game messages during login&quot;">​</a></h2><p>While the connection screen is up, <a href="/gtps-guide/messages/3-game-message">GAME_MESSAGE (3)</a> texts from the server reach it through <code>GameTextMessage</code> (<code>0x1b737ac</code>). The connection screen also handles <code>OnSendToServer</code>, <code>OnReconnect</code> (&quot;Reconnect requested.&quot;) and <code>OnGetDeeplinkData</code> (<code>0x1b6d8c4</code>).</p><table tabindex="0"><thead><tr><th><code>action|</code></th><th>What the client does</th></tr></thead><tbody><tr><td><code>request_token</code></td><td>starts the whole login again from step 1, at most 3 times (&quot;Get request_token, retry login&quot;). After that: &quot;…fail to login…&quot; and a <strong>Retry login</strong> button</td></tr><tr><td><code>request_captcha</code></td><td>reads <code>url|</code> and <code>silentRequest|</code>. Without <code>silentRequest|1</code> it opens <code>url</code> in the WebView. With it, it loads <code>url&amp;showCaptcha=false</code> in the background. If that JSON says <code>success</code> the login starts again. If it says <code>showcaptcha</code> the page is shown. On some platforms the client also shows &quot;<code> `2Please solve the captcha and press continue login button.</code> ``&quot; and a <strong>Continue login</strong> button</td></tr><tr><td><code>set_url</code></td><td>reads <code>url|</code> and <code>label|</code> and shows a button with that label that opens the link</td></tr></tbody></table><p><code>action|log</code>, <code>logoff</code>, <code>play_sfx</code>, <code>play_music</code>, <code>add_notification</code> and <code>logon_fail</code> are handled before this, in every screen (<code>0x1372d28</code>).</p><h2 id="errors-the-player-sees" tabindex="-1">Errors the player sees <a class="header-anchor" href="#errors-the-player-sees" aria-label="Permalink to &quot;Errors the player sees&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Text</th><th>When</th></tr></thead><tbody><tr><td>the <code>maint</code> text</td><td>server_data.php has a <code>maint</code> value</td></tr><tr><td>the <code>error</code> message, with an update button for code 1000</td><td>server_data.php has an <code>error</code> line</td></tr><tr><td>&quot;<code> `4Unable to connect to the network.</code> ``&quot;</td><td>the HTTP request failed</td></tr><tr><td>&quot;<code> `4During login request an error occurred: fail to login. Please try to login again.</code> ``&quot;</td><td>server_data.php failed 4 times, or <code>request_token</code> came more than 3 times</td></tr><tr><td>&quot;<code> `4During login request an error occurred: fail to get validation response. Please try to login again.</code> ``&quot;</td><td>the login site&#39;s JSON couldn&#39;t be read, or <code>status</code>/<code>token</code> was missing</td></tr><tr><td>&quot;<code> `4During login request an error occurred: fail to get validation status. Please try to login again.</code> ``&quot;</td><td>unknown <code>status</code></td></tr><tr><td>&quot;<code> `4During login request error occurred: can&#39;t parse page content. Please try to login again.</code> ``&quot;</td><td>the page text couldn&#39;t be read</td></tr><tr><td>the <code>message</code> in red</td><td><code>status</code> is <code>failed</code></td></tr><tr><td>&quot;<code>`4You don&#39;t have permission to continue playing`</code>&quot;</td><td><code>status</code> is <code>close</code></td></tr></tbody></table><p><small>Connection screen (<code>ConnectionScreenController</code>): server address <code>0x1b6ea04</code>, reply <code>0x1b700fc</code>, token request <code>0x1b71f50</code>, token check <code>0x1b723cc</code>, token received <code>0x1b72ab0</code>, native sign-in <code>0x1b73228</code>, connect <code>0x1b6e778</code>, game messages <code>0x1b737ac</code>; login-site JSON <code>0x1b99a54</code>; WebView bridge <code>com.rtsoft.growtopia.WebViewManager</code>.</small></p>',48)])])}const u=t(n,[["render",s]]);export{g as __pageData,u as default};
